<script setup lang="ts">
import { computed, ref } from 'vue'
import { app, setTool, setEditing, editor, game } from '../session'
import { models } from '../core/catalog'
import { THEMES, FLOORS, WALLS, E, BIOMES, type ThemeId } from '../core/defs'
import { STAMPS } from '../core/gen/expand'
import { ROOM_TYPES } from '../core/gen/furnish'
import type { Tool } from '../engine/editor'
import Icon from './Icon.vue'
import Thumb from './Thumb.vue'
const tools: { t: Tool; i: string; n: string; out?: boolean }[] = [{ t: 'select', i: 'hand', n: 'Select and move' }, { t: 'prop', i: 'wooden-chair', n: 'Place things' }, { t: 'room', i: 'doorway', n: 'Draw a room' }, { t: 'wall', i: 'brick-wall', n: 'Walls and doors' }, { t: 'floor', i: 'stone-path', n: 'Paint floor' }, { t: 'cave', i: 'mountain-cave', n: 'Dig cave' }, { t: 'liquid', i: 'waves', n: 'Water and lava' }, { t: 'height', i: 'stairs-goal', n: 'Raise floor' }, { t: 'stairs', i: 'stairs', n: 'Stairs' }, { t: 'terrain', i: 'mountains', n: 'Shape the land', out: true }, { t: 'stamp', i: 'house', n: 'Buildings', out: true }, { t: 'grow', i: 'expand', n: 'Grow rooms from here' }, { t: 'roominfo', i: 'scroll-quill', n: 'Room details' }, { t: 'erase', i: 'broom', n: 'Erase' }]
const s = app.tool; const q = ref(''), cat = ref('all'), open = ref(true); const cats = ['all', 'masonry', 'light', 'dungeon', 'furnish', 'village', 'nature']
const nice = (t: string) => { const w = t.replace(/_/g, ' '); return w[0].toUpperCase() + w.slice(1) }
const list = computed(() => models().filter(m => m.fit !== 'leaf' && m.fit !== 'spiral' && m.fit !== 'stairs' && (cat.value === 'all' || m.cat === cat.value) && (!q.value || (m.id.replace(/_/g, ' ') + ' ' + m.tags.join(' ')).toLowerCase().includes(q.value.toLowerCase()))))
const floors = FLOORS.filter(f => f && f !== 'terrain'), walls = WALLS.filter(w => w !== 'rock'); const edges: [number, string][] = [[E.Wall, 'Wall'], [E.Door, 'Door'], [E.GateA, 'Double gate'], [E.Iron, 'Iron door'], [E.Cell, 'Cell door'], [E.Secret, 'Secret door'], [E.Arch, 'Arch'], [E.Window, 'Window'], [E.Slit, 'Arrow slit'], [E.Grille, 'Bars'], [E.Merlon, 'Battlement'], [E.Rail, 'Railing'], [E.Fence, 'Fence'], [E.Ruin, 'Ruined wall'], [E.None, 'Nothing']]
const pick = (t: Tool) => { setTool({ tool: t }); open.value = true }; const title = computed(() => tools.find(x => x.t === s.tool)?.n ?? ''); const hasLand = computed(() => !!game.value?.world?.terrain)
const tips: Partial<Record<Tool, string>> = { select: 'Click a thing to choose it, drag to move it. R turns, Delete removes.', prop: 'Click to place. Wall pieces snap to walls, small things land on tables. R turns.', room: 'Drag out a rectangle.', wall: 'Point at the edge of a square. Drag to draw a run.', floor: 'Drag to paint. Underground, walls follow.', cave: 'Drag to hollow out living rock.', liquid: 'Drag over a floor to flood it.', height: 'Drag to raise or sink the floor by a foot at a time.', stairs: 'Click where the foot of the stair should be.', terrain: 'Hold and drag over open land.', stamp: 'Click open ground. R turns it.', grow: 'Click a room. New ones grow from its walls.', roominfo: 'Click a room to name it, theme it or refurnish it.', erase: 'Drag to clear.' }
const rotS = () => setTool({ rot: (s.rot + 1) % 4 })
</script>
<template>
  <nav class="tools" aria-label="Tools"><button class="fin" @click="setEditing(false)">Done</button><template v-for="t in tools" :key="t.t"><button v-if="!t.out || hasLand" class="tl" :class="{ on: s.tool === t.t }" :aria-label="t.n" :title="t.n" @click="pick(t.t)"><Icon :n="t.i" /></button></template></nav>
  <section class="opt2 slate" :class="{ shut: !open }"><div class="in">
    <header @click="open = !open"><h2>{{ title }}</h2><button class="fold" :aria-label="open ? 'Fold' : 'Unfold'">{{ open ? '−' : '+' }}</button></header>
    <div v-show="open" class="body scroll">
      <p class="tip muted">{{ tips[s.tool] }}</p>
      <template v-if="s.tool === 'prop'">
        <input v-model="q" class="field" placeholder="Search 200 things: chest, tomb, oak…" aria-label="Search things">
        <div class="chips cat"><button v-for="c in cats" :key="c" class="chip s" :class="{ on: cat === c }" @click="cat = c">{{ nice(c) }}</button></div>
        <div class="grid"><button v-for="m in list" :key="m.id" class="it" :class="{ on: s.model === m.id }" :title="nice(m.id)" @click="setTool({ model: m.id })"><Thumb :id="m.id" kind="prop" :size="66" /></button></div>
        <div class="row" style="margin-top:8px"><b>{{ nice(s.model) }}</b><span style="flex:1" /><button class="chip s" :class="{ on: s.snap }" @click="setTool({ snap: !s.snap })">Snap</button></div>
        <label class="lab" for="sc">Size {{ s.scale.toFixed(2) }}</label><input id="sc" type="range" min=".4" max="2.5" step=".05" :value="s.scale" @input="setTool({ scale: +($event.target as HTMLInputElement).value })">
        <div class="row"><button class="btn sm" @click="editor!.rotate(-Math.PI / 4)">Turn</button><button class="btn sm" @click="editor!.rotate(Math.PI / 4)">Turn</button></div>
      </template>
      <template v-else-if="s.tool === 'select'">
        <div v-if="app.sel"><div class="row"><Thumb :id="app.sel.m" kind="prop" :size="76" /><b style="font:700 20px var(--serif)">{{ nice(app.sel.m) }}</b></div><label class="lab" for="ss">Size</label><input id="ss" type="range" min=".3" max="3" step=".05" :value="app.sel.s" @change="editor!.change({ s: +($event.target as HTMLInputElement).value }, 'Resize')"><label class="lab" for="sr">Facing</label><input id="sr" type="range" min="0" max="6.283" step=".1309" :value="((app.sel.r % 6.283) + 6.283) % 6.283" @change="editor!.change({ r: +($event.target as HTMLInputElement).value }, 'Turn')"><label class="lab" for="sy">Height off the floor</label><input id="sy" type="range" min="-1" max="3.5" step=".05" :value="app.sel.y - app.sel.l * 4" @change="editor!.change({ y: app.sel!.l * 4 + +($event.target as HTMLInputElement).value }, 'Lift')"><div class="chips" style="margin-top:10px"><button class="btn sm" @click="editor!.duplicate()">Copy</button><button class="btn sm" @click="editor!.remove()">Remove</button></div></div><p v-else class="muted">Nothing chosen.</p>
      </template>
      <template v-else-if="s.tool === 'room'"><span class="lab">Purpose</span><div class="chips"><button v-for="t in ROOM_TYPES" :key="t" class="chip s" :class="{ on: s.roomType === t }" @click="setTool({ roomType: t })">{{ nice(t) }}</button></div><button class="chip" style="margin-top:8px" :class="{ on: s.furnish }" @click="setTool({ furnish: !s.furnish })">Furnish it for me</button><span class="lab">Theme</span><div class="chips"><button v-for="t in THEMES" :key="t.id" class="chip s" :class="{ on: s.theme === t.id }" @click="setTool({ theme: t.id as ThemeId, wall: t.wall, floor: t.floor, ceil: t.ceil })">{{ t.name }}</button></div><span class="lab">Ceiling</span><div class="chips"><button v-for="c in ([[4, 'Vault'], [1, 'Stone'], [2, 'Beams'], [0, 'Open']] as const)" :key="c[0]" class="chip s" :class="{ on: s.ceil === c[0] }" @click="setTool({ ceil: c[0] })">{{ c[1] }}</button></div></template>
      <template v-if="['wall', 'room'].includes(s.tool)"><template v-if="s.tool === 'wall'"><span class="lab">What</span><div class="chips"><button v-for="e in edges" :key="e[0]" class="chip s" :class="{ on: s.edge === e[0] }" @click="setTool({ edge: e[0] })">{{ e[1] }}</button></div></template><span class="lab">Wall</span><div class="sw"><button v-for="w in walls" :key="w" :class="{ on: s.wall === w }" :title="nice(w)" :aria-label="nice(w)" :style="{ backgroundImage: `url(./tex/lo/${w === 'timber' || w === 'wattle' ? 'plaster' : w}.c.webp)` }" @click="setTool({ wall: w })"><i v-if="w === 'timber'" /></button></div></template>
      <template v-if="['floor', 'room'].includes(s.tool)"><span class="lab">Floor</span><div class="sw"><button v-for="f in floors" :key="f" :class="{ on: s.floor === f }" :title="nice(f)" :aria-label="nice(f)" :style="{ backgroundImage: `url(./tex/lo/${f}.c.webp)` }" @click="setTool({ floor: f })" /></div></template>
      <template v-if="s.tool === 'liquid'"><div class="chips"><button v-for="l in (['water', 'lava', 'none'] as const)" :key="l" class="chip" :class="{ on: s.liquid === l }" @click="setTool({ liquid: l })">{{ { water: 'Water', lava: 'Lava', none: 'Dry it' }[l] }}</button></div></template>
      <template v-if="s.tool === 'height'"><div class="chips"><button class="chip" :class="{ on: s.raise > 0 }" @click="setTool({ raise: 1 })">Raise</button><button class="chip" :class="{ on: s.raise < 0 }" @click="setTool({ raise: -1 })">Sink</button></div></template>
      <template v-if="s.tool === 'erase'"><div class="chips"><button class="chip" :class="{ on: s.raise !== 0 }" @click="setTool({ raise: 1 })">Everything</button><button class="chip" :class="{ on: s.raise === 0 }" @click="setTool({ raise: 0 })">Only things</button></div></template>
      <template v-if="s.tool === 'stairs'"><span class="lab">Leads</span><div class="chips"><button class="chip" :class="{ on: s.stairDown }" @click="setTool({ stairDown: true })">Down from this floor</button><button class="chip" :class="{ on: !s.stairDown }" @click="setTool({ stairDown: false })">Up from this floor</button></div><span class="lab">Climbs toward</span><div class="chips"><button v-for="(d, i) in ['East', 'South', 'West', 'North']" :key="d" class="chip" :class="{ on: s.stairDir === i }" @click="setTool({ stairDir: i })">{{ d }}</button></div></template>
      <template v-if="s.tool === 'terrain'"><div class="chips"><button v-for="t in ([['raise', 'Raise'], ['lower', 'Lower'], ['smooth', 'Smooth'], ['flat', 'Level'], ['paint', 'Paint']] as const)" :key="t[0]" class="chip" :class="{ on: s.terrain === t[0] }" @click="setTool({ terrain: t[0] })">{{ t[1] }}</button></div><div v-if="s.terrain === 'paint'" class="sw" style="margin-top:8px"><button v-for="(l, i) in BIOMES[app.env.biome as keyof typeof BIOMES].layers" :key="i" :class="{ on: s.layer === i }" :aria-label="l" :style="{ backgroundImage: `url(./tex/lo/${l}.c.webp)` }" @click="setTool({ layer: i })" /></div><label class="lab" for="st">Strength</label><input id="st" type="range" min=".1" max="1" step=".05" :value="s.strength" @input="setTool({ strength: +($event.target as HTMLInputElement).value })"></template>
      <template v-if="s.tool === 'stamp'"><div class="chips"><button v-for="t in STAMPS" :key="t.id" class="chip st" :class="{ on: s.stamp === t.id }" @click="setTool({ stamp: t.id })">{{ t.name }}</button></div><button class="btn sm" style="margin-top:8px" @click="rotS">Door faces {{ ['south', 'east', 'north', 'west'][s.rot % 4] }}</button></template>
      <template v-if="['grow', 'cave'].includes(s.tool)"><span class="lab">Theme</span><div class="chips"><button v-for="t in THEMES" :key="t.id" class="chip s" :class="{ on: s.theme === t.id }" @click="setTool({ theme: t.id as ThemeId })">{{ t.name }}</button></div></template>
      <template v-if="s.tool === 'grow'"><label class="lab" for="gc">Rooms: {{ s.count }}</label><input id="gc" type="range" min="1" max="15" :value="s.count" @input="setTool({ count: +($event.target as HTMLInputElement).value })"></template>
      <template v-if="['floor', 'cave', 'liquid', 'height', 'erase', 'terrain'].includes(s.tool)"><label class="lab" for="br">Brush: {{ s.brush }} {{ s.brush > 1 ? 'squares' : 'square' }}</label><input id="br" type="range" min="1" max="9" :value="s.brush" @input="setTool({ brush: +($event.target as HTMLInputElement).value })"></template>
    </div>
  </div></section>
</template>
<style scoped>
.tools{position:absolute;left:var(--safe-l);top:calc(84px + var(--safe-t));display:flex;flex-direction:column;max-height:calc(100% - 100px);flex-wrap:wrap;align-content:flex-start;background:var(--navy);pointer-events:auto}.tl{width:46px;height:43px;display:grid;place-items:center;color:var(--tx2)}.tl svg{width:25px;height:25px}.tl:hover{background:var(--navy2);color:var(--tx)}.tl.on{background:var(--spot);color:var(--on-spot)}.fin{height:40px;padding:0 6px;font-weight:600;background:var(--paper);color:var(--ink);text-align:center;font-size:15px}
.opt2{position:absolute;right:0;top:0;bottom:0;width:var(--col);display:flex;pointer-events:auto}.opt2.shut{bottom:auto}.in{flex:1;min-width:0;display:flex;flex-direction:column;min-height:0}
header{display:flex;align-items:center;padding:14px 14px 8px 20px;cursor:pointer}h2{flex:1;font-size:28px}.fold{font-size:25px;width:34px;text-align:center}
.body{min-width:0;overflow-x:hidden;padding:0 20px 18px;min-height:0;flex:1}.tip{margin:0 0 10px}.cat{margin:10px 0}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(68px,1fr));gap:2px;max-height:50vh;overflow-y:auto;scrollbar-width:thin}.it{aspect-ratio:1;display:grid;place-items:center;background:var(--navy2)}.it:hover{background:var(--navy3)}.it.on{background:var(--spot)}
.sw{display:grid;grid-template-columns:repeat(auto-fill,minmax(44px,1fr));gap:3px}.sw button{aspect-ratio:1;background-size:cover;position:relative}.sw button.on{outline:4px solid var(--spot);outline-offset:-4px}.sw i{position:absolute;inset:0;background:linear-gradient(90deg,#3a2413 18%,transparent 18% 82%,#3a2413 82%)}
@media (max-width:899px),(max-height:520px){.tools{top:auto;bottom:var(--safe-b);left:0;right:0;flex-direction:row;flex-wrap:nowrap;overflow-x:auto;max-height:none;scrollbar-width:none}.tl{flex:none}.fin{height:43px;flex:none;padding:0 14px}.opt2{left:0;right:0;width:auto;top:auto;bottom:calc(43px + var(--safe-b));max-height:44vh}.grid{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:72px;max-height:none;overflow-x:auto}}
@media (max-height:520px) and (min-width:900px){.opt2{left:auto;width:min(380px,56vw);max-height:80vh}}
</style>
